import {csvRecords,normalize,pendingItems} from './core.mjs';
const $=s=>document.querySelector(s),uid=()=>crypto.randomUUID(),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db,state={trips:[]},selected=null,tab='overview',submitAction=null,importKind='people',folderTarget=null,toastTimer;
const dbReady=new Promise((resolve,reject)=>{const r=indexedDB.open('equip-viatges-v0',1);r.onupgradeneeded=()=>{r.result.createObjectStore('data');r.result.createObjectStore('folders');};r.onsuccess=()=>{db=r.result;resolve(db)};r.onerror=()=>reject(r.error)});
async function read(store,key){await dbReady;return new Promise((resolve,reject)=>{const r=db.transaction(store).objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function write(store,key,value){await dbReady;return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
async function remove(store,key){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function persist(){await write('data','state',state);render()}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5500)}
function fail(e){console.error(e);toast(e.name==='QuotaExceededError'?'Emmagatzematge ple. Prova amb una carpeta més petita.':e.message||'No s’ha pogut completar l’operació.')}
const trip=()=>state.trips.find(t=>t.id===selected),date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('ca-ES',{day:'numeric',month:'short',year:'numeric'}):'Dates per confirmar';
const badge=s=>`<span class="status ${['Comprat','Fet','Reservat'].includes(s)?'done':s==='No cal'?'neutral':''}">${esc(s||'Pendent')}</span>`;
const sport=s=>`<span class="pill ${s==='Ciclisme'?'cycle':''}">${s==='Ciclisme'?'↗':'❄'} ${esc(s)}</span>`;
const empty=(title,description,button='')=>`<div class="empty"><div class="empty-icon">▤</div><h3>${title}</h3><p>${description}</p>${button}</div>`;
function render(){const t=trip();$('#crumb').textContent=t?t.name:'Viatges';if(!t){selected=null;renderHome();return}renderTrip(t)}
function renderHome(){const pending=state.trips.reduce((n,t)=>n+pendingItems(t).length,0);$('#app').innerHTML=`<div class="page-head"><div><h1>Els teus viatges</h1><p>Tota la logística de l’equip, en un mateix lloc.</p></div><button class="button" data-action="new-trip">＋ Nou viatge</button></div><div class="stats"><div class="stat"><span>Viatges organitzats</span><strong>${state.trips.length}</strong></div><div class="stat"><span>Participants</span><strong>${state.trips.reduce((n,t)=>n+t.people.length,0)}</strong></div><div class="stat"><span>Gestions pendents</span><strong>${pending}<small>per revisar</small></strong></div></div><div class="section-head"><h2>Viatges</h2><span class="muted small">${state.trips.length} en aquest espai</span></div>${state.trips.length?`<div class="grid">${state.trips.map(t=>`<button class="trip-card" data-action="open-trip" data-id="${t.id}"><div class="trip-top">${sport(t.sport)}<span class="muted">↗</span></div><div class="trip-content"><h3>${esc(t.name)}</h3><p>⌖ ${esc(t.destination||'Destinació per confirmar')}</p><p>${date(t.start)}${t.end?' — '+date(t.end):''}</p></div><div class="trip-footer"><span>${t.people.length} participants · ${t.vehicles.length} vehicles</span><span>${t.folder?'▣ Carpeta':'Sense carpeta'}</span></div></button>`).join('')}</div>`:empty('El primer viatge comença aquí','Crea un viatge, vincula la seva carpeta i afegeix-hi les persones i els transports.','<button class="button" data-action="new-trip">＋ Crear el primer viatge</button>')}<div class="notice"><strong>El teu espai de treball local.</strong> Els documents es llegeixen només amb el teu permís. Les dades d’aquesta versió es guarden en aquest navegador, no es comparteixen amb l’equip. Exporta una còpia abans de canviar d’ordinador o esborrar les dades del navegador.</div><div class="mobile-backup actions"><button class="button secondary" data-action="backup">Exportar dades</button><button class="button secondary" data-action="restore">Restaurar còpia</button></div>`}
function renderTrip(t){$('#app').innerHTML=`<button class="back" data-action="home">← Tots els viatges</button><div class="page-head"><div>${sport(t.sport)}<h1 style="margin-top:12px">${esc(t.name)}</h1><p>${esc(t.destination||'Destinació per confirmar')} · ${date(t.start)}${t.end?' — '+date(t.end):''}</p></div><div class="actions"><button class="button secondary" data-action="edit-trip">Editar viatge</button></div></div><nav class="tabs" aria-label="Seccions del viatge">${[['overview','Resum'],['people','Participants',t.people.length],['vehicles','Transports',t.vehicles.length],['files','Documents',t.files.length]].map(([key,label,n])=>`<button class="tab ${tab===key?'active':''}" data-action="tab" data-id="${key}" aria-current="${tab===key?'page':'false'}">${label}${n!==undefined?' · '+n:''}</button>`).join('')}</nav><div id="tripContent">${tab==='overview'?overview(t):tab==='people'?people(t):tab==='vehicles'?vehicles(t):files(t)}</div>`}
function folderPanel(t){return `<div class="folder-panel"><div class="folder-icon">▣</div><div><h3>${esc(t.folder?.name||'Vincula la carpeta del viatge')}</h3><p>${t.folder?`${t.files.length} documents · ${t.folder.mode==='handle'?'Lectura amb permís':'Còpia local al navegador'}`:'Selecciona una carpeta del teu ordinador per tenir els documents a mà.'}</p>${t.folder?`<p>Última lectura: ${new Date(t.folder.updated).toLocaleString('ca-ES')}</p>`:''}</div><div class="actions">${t.folder?'<button class="button lime" data-action="refresh-folder">↻ Actualitzar</button>':''}<button class="button ${t.folder?'secondary':'lime'}" data-action="link-folder">${t.folder?'Canviar carpeta':'Vincular carpeta'}</button></div></div>`}
function overview(t){const items=pendingItems(t);return `${folderPanel(t)}<div class="stats"><div class="stat"><span>Participants</span><strong>${t.people.length}</strong></div><div class="stat"><span>Vehicles</span><strong>${t.vehicles.length}</strong></div><div class="stat"><span>Gestions pendents</span><strong>${items.length}</strong></div></div><div class="split"><section class="panel"><h3>Per deixar-ho tot a punt</h3>${items.length?`<ul class="pending-list">${items.map(s=>`<li><b>!</b> ${esc(s)}</li>`).join('')}</ul>`:`<p class="muted">${t.people.length?'No hi ha gestions pendents en les fitxes actuals.':'Afegeix els participants per començar a revisar els bitllets, el check-in i els transports.'}</p>`}<button class="text-button" data-action="tab" data-id="people">Gestionar participants →</button></section><section class="panel"><h3>Informació del viatge</h3><dl class="detail-list"><div><dt>Responsable</dt><dd>${esc(t.coordinator||'Per assignar')}</dd></div><div><dt>Telèfon</dt><dd>${esc(t.phone||'Sense indicar')}</dd></div><div><dt>Allotjament</dt><dd>${esc(t.hotel||'Sense indicar')}</dd></div><div><dt>Equip</dt><dd>${esc(t.sport)}</dd></div></dl>${t.notes?`<p class="small" style="white-space:pre-wrap">${esc(t.notes)}</p>`:''}</section></div>`}
function people(t){return `<div class="section-head"><h2>Participants</h2><div class="actions"><button class="button secondary" data-action="template" data-id="people">Plantilla CSV ↓</button><button class="button secondary" data-action="import" data-id="people">Importar CSV</button><button class="button" data-action="new-person">＋ Participant</button></div></div>${t.people.length?`<div class="table-wrap"><table><thead><tr><th>PERSONA / ORIGEN</th><th>BITLLET</th><th>CHECK-IN</th><th>ARRIBADA</th><th>TRANSPORT / RECOLLIDA</th><th></th></tr></thead><tbody>${t.people.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.origin||'Origen pendent')}${p.phone?' · '+esc(p.phone):''}</small></td><td>${badge(p.ticket)}</td><td>${badge(p.checkin)}</td><td>${esc(p.arrival||'Per confirmar')}</td><td>${esc(t.vehicles.find(v=>v.id===p.vehicle)?.name||p.pickup||'Per assignar')}<small>${esc(p.parking||'')}</small></td><td><button class="edit-button" data-action="edit-person" data-id="${p.id}">Editar</button></td></tr>`).join('')}</tbody></table></div>`:empty('Qui viatja amb l’equip?','Afegeix participants o importa un CSV exportat des d’Excel. Podràs revisar les dades abans de guardar-les.','<button class="button" data-action="new-person">＋ Afegir participant</button>')}<p class="muted small">Els estats es confirmen manualment. Un document a la carpeta no dona el bitllet o el check-in per resolt.</p>`}
function vehicles(t){return `<div class="section-head"><h2>Transports</h2><div class="actions"><button class="button secondary" data-action="template" data-id="vehicles">Plantilla CSV ↓</button><button class="button secondary" data-action="import" data-id="vehicles">Importar CSV</button><button class="button" data-action="new-vehicle">＋ Vehicle</button></div></div>${t.vehicles.length?`<div class="grid">${t.vehicles.map(v=>{const ps=t.people.filter(p=>p.vehicle===v.id);return `<section class="panel"><div class="section-head" style="margin-top:0"><h3>${esc(v.name)}</h3><span class="pill">${esc(v.direction)}</span></div><dl class="detail-list"><div><dt>Conductor</dt><dd>${esc(v.driver||'Per assignar')}</dd></div><div><dt>Telèfon</dt><dd>${esc(v.phone||'Sense indicar')}</dd></div><div><dt>Sortida</dt><dd>${esc(v.origin||'Per confirmar')}</dd></div><div><dt>Hora</dt><dd>${esc(v.departure||'Per confirmar')}</dd></div><div><dt>Places per a passatgers</dt><dd>${v.seats||'Sense indicar'}</dd></div><div><dt>Aparcament</dt><dd>${esc(v.parking||'Sense indicar')}</dd></div></dl><p class="small"><strong>Passatgers assignats:</strong> ${ps.length?ps.map(p=>esc(p.name)).join(', '):'Cap'}</p>${v.passengers?`<p class="small"><strong>Passatgers indicats al CSV:</strong> ${esc(v.passengers)}</p>`:''}${v.notes?`<p class="small muted">${esc(v.notes)}</p>`:''}<button class="edit-button" data-action="edit-vehicle" data-id="${v.id}">Editar transport</button></section>`}).join('')}</div>`:empty('Cada trajecte, ben organitzat','Crea un vehicle per trajecte: anada o tornada. Indica el conductor, la sortida, l’hora i les places.','<button class="button" data-action="new-vehicle">＋ Afegir vehicle</button>')}`}
function files(t){return `${folderPanel(t)}<div class="notice">${t.folder?.mode==='handle'?'La carpeta es llegeix quan prems «Actualitzar». Pot ser necessari tornar a donar permís després de tancar el navegador.':'Si el navegador no permet vincular carpetes, es guarda una còpia local dels fitxers seleccionats. Per actualitzar-la, torna a seleccionar la carpeta.'} No es modifica ni s’envia cap document del teu ordinador a un servidor.</div>${t.files.length?`<div class="table-wrap"><table><thead><tr><th>DOCUMENT</th><th>MIDA</th><th>MODIFICAT</th><th></th></tr></thead><tbody>${t.files.map((f,i)=>`<tr><td class="file-path"><strong>${esc(f.name)}</strong><small>${esc(f.path)}</small></td><td class="nowrap">${formatSize(f.size)}</td><td>${new Date(f.modified).toLocaleDateString('ca-ES')}</td><td><div class="row-links"><button class="edit-button" data-action="download-file" data-id="${i}">Descarregar</button>${/\.(csv|tsv)$/i.test(f.name)?`<button class="edit-button" data-action="import-file" data-id="${i}">Importar dades</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Els documents del viatge','Vincula una carpeta amb els bitllets, les reserves i els fulls de transport. Els CSV es poden importar com a fitxes.')}`}
function formatSize(n){return n>1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB'}
function field(label,key,value='',type='text',full=false,required=false){return `<label class="field ${full?'full':''}">${label}<input name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="1"':''}></label>`}
function select(label,key,value,options){return `<label class="field">${label}<select name="${key}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${value===v?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`}
function notes(value){return `<label class="field full">Notes<textarea name="notes">${esc(value||'')}</textarea></label>`}
function modal(title,html,fn,label='Guardar'){submitAction=fn;$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#submitModal').textContent=label;$('#modal').showModal()}
function tripForm(edit=false){const t=edit?trip():{};modal(edit?'Editar viatge':'Nou viatge',`<div class="form-grid">${field('Nom del viatge','name',t.name,'text',true,true)}${select('Equip','sport',t.sport||'Esquí',['Esquí','Ciclisme'])}${field('Destinació','destination',t.destination)}${field('Data de sortida','start',t.start,'date')}${field('Data de tornada','end',t.end,'date')}${field('Responsable','coordinator',t.coordinator)}${field('Telèfon','phone',t.phone,'tel')}${field('Allotjament','hotel',t.hotel,'text',true)}${notes(t.notes)}</div>`,async data=>{if(data.start&&data.end&&data.end<data.start)throw Error('La tornada no pot ser anterior a la sortida.');if(edit)Object.assign(t,data);else{const n={...data,id:uid(),people:[],vehicles:[],files:[],folder:null};state.trips.push(n);selected=n.id;tab='overview'}await persist();toast(edit?'Viatge actualitzat':'Viatge creat. Ja pots vincular-hi una carpeta.')})}
function personForm(id){const t=trip(),p=t.people.find(p=>p.id===id)||{};modal(id?'Editar participant':'Nou participant',`<div class="form-grid">${field('Nom i cognoms','name',p.name,'text',true,true)}${field('Telèfon','phone',p.phone,'tel')}${field('Origen','origin',p.origin)}${select('Bitllet','ticket',p.ticket||'Pendent',['Pendent','Comprat','No cal'])}${select('Check-in','checkin',p.checkin||'Pendent',['Pendent','Fet','No cal'])}${field('Arribada · dia, hora i lloc','arrival',p.arrival,'text',true)}${select('Vehicle assignat','vehicle',p.vehicle||'',[['','Sense assignar'],...t.vehicles.map(v=>[v.id,`${v.name} · ${v.direction}`])])}${field('Recollida · persona i lloc','pickup',p.pickup)}${field('Aparcament','parking',p.parking,'text',true)}${notes(p.notes)}</div>${id?'<button type="button" class="text-button error" data-action="delete-person" data-id="'+id+'">Eliminar participant</button>':''}`,async data=>{if(id)Object.assign(p,data);else t.people.push({...data,id:uid()});await persist();toast('Participant guardat')})}
function vehicleForm(id){const t=trip(),v=t.vehicles.find(v=>v.id===id)||{};modal(id?'Editar transport':'Nou transport',`<div class="form-grid">${field('Vehicle · nom o matrícula','name',v.name,'text',false,true)}${select('Trajecte','direction',v.direction||'Anada',['Anada','Tornada'])}${field('Conductor','driver',v.driver)}${field('Telèfon del conductor','phone',v.phone,'tel')}${field('Punt de sortida','origin',v.origin)}${field('Dia i hora de sortida','departure',v.departure)}${field('Places per a passatgers (sense conductor)','seats',v.seats||'','number')}${field('Aparcament / reserva','parking',v.parking)}${field('Passatgers indicats / anotacions','passengers',v.passengers,'text',true)}${notes(v.notes)}</div><p class="small muted">Assigna les persones des de la seva fitxa de participant. Les anotacions de passatgers no creen assignacions automàtiques.</p>${id?'<button type="button" class="text-button error" data-action="delete-vehicle" data-id="'+id+'">Eliminar vehicle</button>':''}`,async data=>{data.seats=Number(data.seats)||0;if(id)Object.assign(v,data);else t.vehicles.push({...data,id:uid()});await persist();toast('Transport guardat')})}
async function scan(handle){const out=[];async function walk(dir,prefix=''){for await(const [name,entry]of dir.entries()){if(name.startsWith('.'))continue;const path=prefix+name;if(entry.kind==='directory')await walk(entry,path+'/');else{if(out.length>=2000)throw Error('La carpeta supera els 2.000 fitxers. Selecciona una carpeta específica del viatge.');const f=await entry.getFile();out.push({name,path,size:f.size,modified:f.lastModified})}}}await walk(handle);return out.sort((a,b)=>a.path.localeCompare(b.path))}
async function linkFolder(){const t=trip();if(!window.showDirectoryPicker){folderTarget=t.id;$('#folderInput').click();return}try{const handle=await window.showDirectoryPicker({mode:'read'});toast('Llegint la carpeta…');const list=await scan(handle);await write('folders',t.id,{handle});t.folder={name:handle.name,mode:'handle',updated:Date.now()};t.files=list;await persist();toast(`${list.length} documents vinculats`)}catch(e){if(e.name!=='AbortError'){if(e.name==='SecurityError'){folderTarget=t.id;$('#folderInput').click()}else fail(e)}}}
async function refreshFolder(){const t=trip();if(!t.folder||t.folder.mode!=='handle'){folderTarget=t.id;$('#folderInput').click();return}const saved=await read('folders',t.id);if(!saved?.handle){toast('Torna a seleccionar la carpeta per recuperar l’accés.');return linkFolder()}if(await saved.handle.requestPermission({mode:'read'})!=='granted')throw Error('Cal donar permís de lectura a la carpeta.');toast('Actualitzant documents…');const list=await scan(saved.handle);t.files=list;t.folder.updated=Date.now();await persist();toast('Carpeta actualitzada')}
async function localFile(t,index){const meta=t.files[index],saved=await read('folders',t.id);if(!saved)throw Error('Torna a vincular la carpeta per accedir als documents.');if(saved.handle){if(await saved.handle.requestPermission({mode:'read'})!=='granted')throw Error('Cal donar permís per llegir el document.');let h=saved.handle;const parts=meta.path.split('/');for(const part of parts.slice(0,-1))h=await h.getDirectoryHandle(part);return await(await h.getFileHandle(parts.at(-1))).getFile()}const f=saved.files?.find(f=>f.path===meta.path)?.file;if(!f)throw Error('Document no disponible. Actualitza la carpeta.');return f}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function template(kind){const content=kind==='people'?'Nom;Telefon;Origen;Arribada;Bitllet;Check-in;Recollida;Aparcament;Notes\r\nPersona exemple;600000000;Girona;Divendres 14:30 - Aeroport;Pendent;Pendent;;;\r\n':'Vehicle;Conductor;Telefon;Origen;Hora;Trajecte;Places;Passatgers;Aparcament;Notes\r\nFurgoneta 1;Conductor exemple;600000000;Girona;Divendres 08:00;Anada;7;;Pendent;Espai per al material\r\n';download(new Blob(['\uFEFF'+content],{type:'text/csv;charset=utf-8'}),`plantilla-${kind==='people'?'participants':'transports'}.csv`)}
function importPreview(text,kind){const records=csvRecords(text,kind),t=trip(),keys=Object.keys(records[0]);if(records.length>2000)throw Error('Importa un màxim de 2.000 files cada vegada.');modal(`Importar ${kind==='people'?'participants':'transports'}`,`<p>${records.length} fitxes detectades. Revisa les dades abans de continuar.</p><div class="csv-preview table-wrap"><table><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${records.slice(0,20).map(r=>`<tr>${keys.map(k=>`<td>${esc(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${records.length>20?'<p class="small">Es mostren les primeres 20 files.</p>':''}<div class="notice">S’afegiran només noms nous. Si el nom ja existeix, se saltarà la fila per conservar les teves correccions. Els passatgers d’un CSV de transports es guarden com a anotació.</div>`,async()=>{const list=kind==='people'?t.people:t.vehicles,known=new Set(list.map(x=>normalize(x.name)));let added=0;for(const r of records){if(known.has(normalize(r.name)))continue;list.push({...r,id:uid(),...(kind==='people'?{vehicle:''}:{})});known.add(normalize(r.name));added++}await persist();toast(`${added} fitxes afegides · ${records.length-added} duplicades omeses`)},'Confirmar importació')}
function backup(){download(new Blob([JSON.stringify({format:'equip-v0',exportedAt:new Date().toISOString(),trips:state.trips},null,2)],{type:'application/json'}),'equip-viatges-copia.json');toast('Còpia exportada. Els documents originals no s’inclouen.')}
const handlers={
'new-trip':()=>tripForm(),'edit-trip':()=>tripForm(true),'open-trip':id=>{selected=id;tab='overview';render()},home:()=>{selected=null;render()},tab:id=>{tab=id;render()},'new-person':()=>personForm(),'edit-person':personForm,'new-vehicle':()=>vehicleForm(),'edit-vehicle':vehicleForm,'link-folder':linkFolder,'refresh-folder':refreshFolder,template,import:kind=>{importKind=kind;$('#csvInput').click()},backup,restore:()=>$('#restoreInput').click(),
'download-file':async index=>{const t=trip(),f=await localFile(t,Number(index));download(f,t.files[index].name)},
'import-file':async index=>{const t=trip(),f=await localFile(t,Number(index)),text=await f.text();modal('Quines dades conté el fitxer?',`<div class="form-grid">${select('Tipus de fitxes','kind','people',[['people','Participants'],['vehicles','Transports']])}</div>`,async data=>{setTimeout(()=>{try{importPreview(text,data.kind)}catch(e){fail(e)}},0)},'Revisar dades')},
'delete-person':id=>{if(!confirm('Vols eliminar aquest participant?'))return;const t=trip();t.people=t.people.filter(p=>p.id!==id);$('#modal').close();return persist()},
'delete-vehicle':id=>{if(!confirm('Vols eliminar aquest vehicle? Els participants quedaran sense aquesta assignació.'))return;const t=trip();t.vehicles=t.vehicles.filter(v=>v.id!==id);t.people.forEach(p=>{if(p.vehicle===id)p.vehicle=''});$('#modal').close();return persist()}
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){const fn=handlers[el.dataset.action];if(fn)Promise.resolve().then(()=>fn(el.dataset.id)).catch(fail)}});
$('#allTrips').onclick=handlers.home;$('#backup').onclick=backup;$('#restore').onclick=handlers.restore;$('#closeModal').onclick=$('#cancelModal').onclick=()=>$('#modal').close();
$('#modalForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));for(const k of Object.keys(data))data[k]=data[k].trim();if('name'in data&&!data.name){toast('Indica un nom.');return}$('#submitModal').disabled=true;try{await submitAction(data);$('#modal').close()}catch(e){fail(e)}finally{$('#submitModal').disabled=false}};
$('#csvInput').onchange=async e=>{try{const f=e.target.files[0];if(f){if(f.size>5*1024*1024)throw Error('El CSV supera els 5 MB.');importPreview(await f.text(),importKind)}}catch(e){fail(e)}finally{e.target.value=''}};
$('#folderInput').onchange=async e=>{try{const fs=Array.from(e.target.files);if(!fs.length)return;const t=state.trips.find(t=>t.id===folderTarget);if(!t)return;if(fs.length>2000)throw Error('Selecciona una carpeta amb menys de 2.000 fitxers.');if(fs.reduce((n,f)=>n+f.size,0)>150*1024*1024)throw Error('La còpia supera els 150 MB. Selecciona una carpeta més petita o fes servir Chrome per vincular-la sense copiar-la.');toast('Guardant els documents al navegador…');const files=fs.filter(f=>!f.webkitRelativePath.split('/').some(x=>x.startsWith('.'))).map(f=>({path:f.webkitRelativePath.split('/').slice(1).join('/'),file:f}));await write('folders',t.id,{files});t.folder={name:fs[0].webkitRelativePath.split('/')[0],mode:'copy',updated:Date.now()};t.files=files.map(({path,file:f})=>({path,name:f.name,size:f.size,modified:f.lastModified})).sort((a,b)=>a.path.localeCompare(b.path));await persist();toast('Carpeta guardada en aquest navegador')}catch(e){fail(e)}finally{e.target.value=''}};
$('#restoreInput').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('La còpia és massa gran.');const data=JSON.parse(await f.text());if(data.format!=='equip-v0'||!Array.isArray(data.trips))throw Error('Aquest fitxer no és una còpia d’Equip.');for(const t of data.trips){if(typeof t.name!=='string'||!Array.isArray(t.people)||!Array.isArray(t.vehicles)||!t.people.every(p=>typeof p.name==='string')||!t.vehicles.every(v=>typeof v.name==='string'))throw Error('La còpia conté dades no vàlides.')}modal('Restaurar còpia',`<p>S’afegiran ${data.trips.length} viatges com a còpies noves. Els viatges actuals es conservaran.</p><p class="muted">Hauràs de tornar a vincular les carpetes dels documents.</p>`,async()=>{for(const source of data.trips){const t=structuredClone(source);t.id=uid();t.name+=' (còpia)';const ids=new Map();t.vehicles.forEach(v=>{const id=uid();ids.set(v.id,id);v.id=id});t.people.forEach(p=>{p.id=uid();p.vehicle=ids.get(p.vehicle)||''});t.files=[];t.folder=null;state.trips.push(t)}await persist();toast('Còpia restaurada')},'Restaurar')}catch(e){fail(e)}finally{e.target.value=''}};
try{state=await read('data','state')||{trips:[]};render()}catch(e){$('#app').innerHTML=empty('No es pot obrir l’espai local','Activa l’emmagatzematge del navegador i torna a carregar la pàgina. Les dades no es poden guardar en aquesta sessió.');fail(e)}
